import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const t="/ascendc.github.io/pr/5487/assets/gather_adds_overall_pipeline.CWLhEGS6.png",c="/ascendc.github.io/pr/5487/assets/gather_adds_execution_flow.bbq4YnHa.png",w=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD与SIMT混合算子实现","link":"/guide/operator_practice/simd_simt_hybrid_operator_impl/simd_simt_hybrid_operator_impl"},{"text":"算子实现","link":"/guide/operator_practice/simd_simt_hybrid_operator_impl/operator_impl"}]},"headers":[],"relativePath":"guide/operator_practice/simd_simt_hybrid_operator_impl/operator_impl.md","filePath":"guide/operator_practice/simd_simt_hybrid_operator_impl/operator_impl.md","outlineHeaders":[{"level":2,"title":"算子功能","slug":"算子功能","link":"#算子功能"},{"level":2,"title":"算子分析","slug":"算子分析","link":"#算子分析"},{"level":2,"title":"核函数（Kernel）定义与实现","slug":"核函数（Kernel）定义与实现","link":"#核函数（Kernel）定义与实现"},{"level":2,"title":"SIMT VF实现","slug":"SIMT-VF实现","link":"#SIMT-VF实现"},{"level":2,"title":"SIMD VF实现","slug":"SIMD-VF实现","link":"#SIMD-VF实现"}],"lastUpdated":1787832553000}'),e={name:"guide/operator_practice/simd_simt_hybrid_operator_impl/operator_impl.md"};function i(_,s,d,o,r,h){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>算子实现</h1><p>以下内容以gather &amp; adds算子为例，介绍SIMD与SIMT混合算子的实现过程。完整代码请参见<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/05_simd_simt_hybrid/00_introduction/simd_simt_gather_and_adds">SIMD与SIMT混合编程实现gather&amp;adds算子样例</a>。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>本样例的目的是通过一个简单的算子实现展示SIMD与SIMT混合编程方式，仅作为功能介绍。</p></div><h2 id="算子功能">算子功能<a class="header-anchor" href="#算子功能">​</a></h2><p>gather &amp; adds算子从长度为100000的一维向量input中，按index指定的位置提取8192个数据，并对提取后的数据执行加1计算。算子输出output中第i个数据为：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">output</span><span class="p">[</span><span class="n">i</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">input</span><span class="p">[</span><span class="n">index</span><span class="p">[</span><span class="n">i</span><span class="p">]]</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">1</span>
</code></pre></div><p>计算过程可拆分为gather和adds两个阶段：gather阶段根据index从input中离散读取数据，并将结果写入Unified Buffer（UB）；adds阶段对UB上的连续中间数据执行加1计算，计算结果原地写回UB，最后将结果数据搬运到GM上的output中。</p><p>其中，gather阶段包含索引映射和离散访问，使用SIMT表达每个线程的数据访问逻辑；adds阶段处理连续数据，使用SIMD完成向量计算。</p><h2 id="算子分析">算子分析<a class="header-anchor" href="#算子分析">​</a></h2><p><strong>图 1</strong> gather &amp; adds算子整体执行流水<br><img src="`+t+'" alt title="gather &amp; adds算子整体执行流水"></p><p>gather &amp; adds算子整体执行流水如图1所示。simt_gather和simd_adds同属Vector流水，按调用顺序执行；将adds结果从UB搬出到GM属于MTE3搬出流水。由于Vector流水与MTE3搬出流水异步并行执行，MTE3搬出操作可能在Vector流水写入adds结果完成前读取UB数据，因此需在搬出前插入同步指令，确保adds结果写入UB后再启动搬出。</p><p><strong>图 2</strong> gather &amp; adds算子执行流程<br><img src="'+c+`" alt title="gather &amp; adds算子执行流程"></p><p>gather &amp; adds算子的详细执行流程如图2所示。基于该流程，按照输入输出、核函数（Kernel）参数、执行配置和VF函数参数的顺序分析gather &amp; adds算子的实现方式。</p><p><strong>输入输出分析：</strong> gather &amp; adds算子有两个输入input和index，输出为output。其中，input为原始数据，index表示需要从input中读取的数据位置，output保存读取并加1后的结果。</p><p>本样例中，input的数据类型为float，shape为[100000]；index的数据类型为uint32_t，shape为[8192]，取值范围为[0, 100000)；output的数据类型与input相同，shape与index相同。算子输入输出<a href="../../technical_appendix/concepts_and_terms/neural_networks_and_operators/data_layout.html">format</a>均为ND。</p><p><strong>核函数（Kernel）名称和参数：</strong> 根据上述输入输出和执行流程，本样例中核函数（Kernel）命名为gather_and_adds_kernel，函数原型如下。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">gather_and_adds_kernel</span><span class="p">(</span>
<span class="w">    </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint32_t</span><span class="o">*</span><span class="w"> </span><span class="n">index</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">input_total_length</span><span class="p">,</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">index_total_length</span><span class="p">)</span>
</code></pre></div><p>当前SIMD与SIMT混合编程仅使用Vector Core（AIV核），核函数（Kernel）可使用<a href="../../programming_guide/language_extension/simd_builtin_keywords.html#section1074418132518">__vector__</a>标识只启动AIV核。</p><p>其中，input_total_length和index_total_length分别表示input和index的长度。gather阶段需要根据index访问input，input_total_length用于校验index中保存的input访问位置是否越界，index_total_length用于校验线程访问index的位置是否越界。</p><p><strong>执行配置：</strong> 明确SIMT线程配置和分核策略。</p><p>本例中每个SIMT线程处理1个数据，单核线程数设置为1024，即单核处理1024个数据。算子输入index长度为8192，核数为8192 / 1024 = 8，单个核调用1次simt_gather函数即可完成本核的gather运算。</p><p><strong>SIMT VF函数名称和参数：</strong> 根据SIMT线程配置策略，本样例中SIMT VF函数命名为simt_gather，参数说明如下。</p><table><thead><tr><th align="left">参数</th><th align="left">参数类型</th><th align="left">说明</th></tr></thead><tbody><tr><td align="left">input</td><td align="left">__gm__ float*</td><td align="left">输入input的GM地址</td></tr><tr><td align="left">index</td><td align="left">__gm__ uint32_t*</td><td align="left">输入index的GM地址</td></tr><tr><td align="left">local_output</td><td align="left">__ubuf__ float*</td><td align="left">SIMT gather阶段的输出地址</td></tr><tr><td align="left">input_total_length</td><td align="left">uint32_t</td><td align="left">input的数据长度</td></tr><tr><td align="left">index_total_length</td><td align="left">uint32_t</td><td align="left">index的数据长度</td></tr><tr><td align="left">output_total_length</td><td align="left">uint32_t</td><td align="left">单核上local_output的数据长度</td></tr></tbody></table><p><strong>SIMD VF函数名称和参数：</strong> 本样例中SIMD VF函数命名为simd_adds，参数说明如下。</p><table><thead><tr><th align="left">参数</th><th align="left">参数类型</th><th align="left">说明</th></tr></thead><tbody><tr><td align="left">output</td><td align="left">__ubuf__ float*</td><td align="left">SIMD adds阶段的输出地址</td></tr><tr><td align="left">input</td><td align="left">__ubuf__ float*</td><td align="left">SIMD adds阶段的输入地址</td></tr><tr><td align="left">count</td><td align="left">uint32_t</td><td align="left">单核处理的数据总量</td></tr><tr><td align="left">one_repeat_size</td><td align="left">uint32_t</td><td align="left">每轮处理的float元素个数</td></tr><tr><td align="left">repeat_times</td><td align="left">uint16_t</td><td align="left">完成count个元素所需的循环次数</td></tr></tbody></table><p>通过以上分析，得到Ascend C gather &amp; adds算子的设计规格如下：</p><p><strong>表 1</strong> gather &amp; adds算子设计规格</p><table><tr><td rowspan="1" align="center">算子类型（OpType）</td><td colspan="4" align="center">Gather_Adds</td></tr><tr><td rowspan="3" align="center">算子输入</td><td align="center">name</td><td align="center">shape</td><td align="center">data type</td><td align="center">format</td></tr><tr><td align="center">input</td><td align="center">100000</td><td align="center">float</td><td align="center">ND</td></tr><tr><td align="center">index</td><td align="center">8192</td><td align="center">uint32_t</td><td align="center">ND</td></tr><tr><td rowspan="1" align="center">算子输出</td><td align="center">output</td><td align="center">8192</td><td align="center">float</td><td align="center">ND</td></tr><tr><td rowspan="1" align="center">核函数（Kernel）名</td><td colspan="4" align="center"><code>gather_and_adds_kernel</code></td></tr><tr><td rowspan="1" align="center">SIMT VF函数名</td><td colspan="4" align="center"><code>simt_gather</code></td></tr><tr><td rowspan="1" align="center">SIMD VF函数名</td><td colspan="4" align="center"><code>simd_adds</code></td></tr></table><h2 id="核函数（Kernel）定义与实现">核函数（Kernel）定义与实现<a class="header-anchor" href="#核函数（Kernel）定义与实现">​</a></h2><p>根据<a href="../../programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/kernel_and_vf_functions.html#zh-cn_topic_0000002571578013_section156822920311">核函数（Kernel）</a>中介绍的规则进行核函数（Kernel）的定义。本样例中，定义gather_and_adds_kernel核函数（Kernel），代码如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">gather_and_adds_kernel</span><span class="p">(</span>
<span class="w">    </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint32_t</span><span class="o">*</span><span class="w"> </span><span class="n">index</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">input_total_length</span><span class="p">,</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">index_total_length</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="p">...</span>
<span class="w">    </span><span class="c1">// 1. 调用SIMT函数获取指定索引的数据</span>
<span class="w">    </span><span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">simt_gather</span><span class="o">&gt;</span><span class="p">(</span>
<span class="w">        </span><span class="n">dim3</span><span class="p">(</span><span class="n">THREAD_COUNT</span><span class="p">),</span><span class="w"> </span><span class="n">input</span><span class="p">,</span><span class="w"> </span><span class="n">index</span><span class="p">,</span><span class="w"> </span><span class="n">local_output</span><span class="p">,</span><span class="w"> </span><span class="n">input_total_length</span><span class="p">,</span>
<span class="w">        </span><span class="n">index_total_length</span><span class="p">,</span><span class="w"> </span><span class="n">index_total_length_per_block</span><span class="p">);</span>

<span class="w">    </span><span class="p">...</span>
<span class="w">    </span><span class="c1">// 2. 调用SIMD函数完成加1操作</span>
<span class="w">    </span><span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">simd_adds</span><span class="o">&gt;</span><span class="p">(</span>
<span class="w">        </span><span class="n">local_output</span><span class="p">,</span><span class="w"> </span><span class="n">local_output</span><span class="p">,</span><span class="w"> </span><span class="n">index_total_length_per_block</span><span class="p">,</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">,</span><span class="w"> </span><span class="n">repeat_times</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// 依赖PIPE_V和PIPE_MTE3流水同步</span>
<span class="w">    </span><span class="n">asc_sync_notify</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_sync_wait</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// 3. 将数据从UB搬运到GM</span>
<span class="w">    </span><span class="n">asc_copy_ub2gm_align</span><span class="p">(</span><span class="n">output</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">index_total_length_per_block</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">block_idx</span><span class="p">,</span><span class="w"> </span><span class="n">local_output</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span>
<span class="w">        </span><span class="n">index_total_length_per_block</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">),</span><span class="w"> </span><span class="n">asc_store_l2_cache_mode</span><span class="o">::</span><span class="n">NORMAL_FIRST_VICTIM</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><p>核函数（Kernel）中先后启动SIMT VF函数simt_gather和SIMD VF函数simd_adds：simt_gather将GM中的离散数据读取到UB，simd_adds对UB上的gather结果执行加1计算，并将结果原地写回UB。</p><p>对于基于SIMD编程计算并写入UB的结果local_output，调用<a href="../../../api/SIMD-API/c_api/vector_datamove/asc_copy_ub2gm_align/asc_copy_ub2gm_align.html">asc_copy_ub2gm_align</a>接口搬出到GM前，需要通过<a href="../../../api/SIMD-API/c_api/sync/asc_sync_notify.html">asc_sync_notify</a>/<a href="../../../api/SIMD-API/c_api/sync/asc_sync_wait.html">asc_sync_wait</a>接口控制Vector计算流水和MTE3搬出流水的同步，确保adds计算结果写入UB后再启动搬出。</p><h2 id="SIMT-VF实现">SIMT VF实现<a class="header-anchor" href="#SIMT-VF实现">​</a></h2><p>根据上述对SIMT VF函数的参数分析，定义SIMT VF函数原型，代码如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">THREAD_COUNT</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1024</span><span class="p">;</span>

<span class="n">__simt_vf__</span><span class="w"> </span><span class="nf">__launch_bounds__</span><span class="p">(</span><span class="n">THREAD_COUNT</span><span class="p">)</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">simt_gather</span><span class="p">(</span>
<span class="w">    </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint32_t</span><span class="o">*</span><span class="w"> </span><span class="n">index</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">local_output</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">input_total_length</span><span class="p">,</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">index_total_length</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">output_total_length</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="p">...</span>
<span class="w">    </span><span class="c1">// 根据当前核号和线程号计算全局index数组中的元素位置</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="p">...</span>
<span class="w">    </span><span class="c1">// 读取线程应获取的数据在输入input中的索引</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">gather_idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">index</span><span class="p">[</span><span class="n">idx</span><span class="p">];</span>
<span class="w">    </span><span class="p">...</span>
<span class="w">    </span><span class="c1">// 将input中索引为gather_idx的数据存到UB上</span>
<span class="w">    </span><span class="n">local_output</span><span class="p">[</span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">input</span><span class="p">[</span><span class="n">gather_idx</span><span class="p">];</span>
<span class="p">}</span>
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>在SIMT编程中，__launch_bounds__(thread_num)是可选配置，用于在编译期指定核函数（Kernel）启动的最大线程数（如果不配置，thread_num默认为1024），使用时请注意：thread_num &gt;= x * y * z （即：asc_vf_call的第一个参数：dim3{x, y, z}）, 线程数thread_num的取值范围为1到2048。最大线程数决定了每个线程可分配的寄存器数量，具体对应关系请见<a href="../../programming_guide/language_extension/simt_builtin_keywords.html#table1715318510594">表5</a>，寄存器用于存储线程中的局部变量，若局部变量的个数超出寄存器个数，容易出现栈溢出等问题。</p></div><p>使用<a href="../../programming_guide/language_extension/simd_simt_hybrid_builtin_keywords.html#__simt_vf__">__simt_vf__</a>函数类型限定符标识SIMT VF函数入口，使其可以被<a href="../../../api/SIMT-API/SIMD_SIMT_hybrid_programming_intro/extended_syntax/kernel_function_config.html#asc_vf_call%E8%B0%83%E7%94%A8">asc_vf_call</a>调用。</p><p>simt_gather函数实现从输入input中获取指定索引的数据。函数中首先计算线程应处理数据的索引，然后通过赋值操作将数据存储到UB上。</p><p>本例中核数设置为8，线程的层次结构为{1024, 1, 1}，数据总量为8192（8 * 1024）。每个线程处理一个index元素，全局index位置计算逻辑如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">uint32_t</span><span class="w"> </span><span class="n">idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
</code></pre></div><p>其中，<a href="../../programming_guide/language_extension/simt_builtin_keywords.html#li1676053814914">blockIdx</a>用于获取当前核id。<a href="../../programming_guide/language_extension/simt_builtin_keywords.html#li076017381191">blockDim</a>用于获取线程三维层次结构{x, y, z}，本例中为{1024, 1, 1}，其中第2，3维度均为1，使用一维层次结构，因此线程数可写作blockDim.x。<a href="../../programming_guide/language_extension/simt_builtin_keywords.html#li7760123814919">threadIdx</a>用于获取三维线程索引{x, y, z}，本例中仅使用第1维x，可通过threadIdx.x获取当前线程的id。</p><h2 id="SIMD-VF实现">SIMD VF实现<a class="header-anchor" href="#SIMD-VF实现">​</a></h2><p>根据上述对SIMD VF函数的参数分析，定义SIMD VF函数原型，代码如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">ADDS_ADDEND</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mf">1.0f</span><span class="p">;</span>

<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">simd_adds</span><span class="p">(</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">repeat_times</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// 初始化SIMD矢量数据寄存器，源操作数</span>
<span class="w">    </span><span class="n">vector_float</span><span class="w"> </span><span class="n">src_reg0</span><span class="p">;</span>
<span class="w">    </span><span class="c1">// 初始化SIMD矢量数据寄存器，目的操作数</span>
<span class="w">    </span><span class="n">vector_float</span><span class="w"> </span><span class="n">dst_reg0</span><span class="p">;</span>
<span class="w">    </span><span class="c1">// 初始化SIMD矢量计算标记寄存器</span>
<span class="w">    </span><span class="n">vector_bool</span><span class="w"> </span><span class="n">mask_reg</span><span class="p">;</span>

<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">repeat_times</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">mask_reg</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_update_mask_b32</span><span class="p">(</span><span class="n">count</span><span class="p">);</span>
<span class="w">        </span><span class="c1">// 从UB搬运数据到SIMD矢量数据寄存器</span>
<span class="w">        </span><span class="n">asc_loadalign</span><span class="p">(</span><span class="n">src_reg0</span><span class="p">,</span><span class="w"> </span><span class="n">input</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">);</span>
<span class="w">        </span><span class="c1">// 调用asc_add_scalar接口完成加1运算</span>
<span class="w">        </span><span class="n">asc_add_scalar</span><span class="p">(</span><span class="n">dst_reg0</span><span class="p">,</span><span class="w"> </span><span class="n">src_reg0</span><span class="p">,</span><span class="w"> </span><span class="n">ADDS_ADDEND</span><span class="p">,</span><span class="w"> </span><span class="n">mask_reg</span><span class="p">);</span>
<span class="w">        </span><span class="c1">// 从SIMD矢量数据寄存器搬运数据到UB</span>
<span class="w">        </span><span class="n">asc_storealign</span><span class="p">(</span><span class="n">output</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">,</span><span class="w"> </span><span class="n">dst_reg0</span><span class="p">,</span><span class="w"> </span><span class="n">mask_reg</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>使用__simd_vf__函数类型限定符标识SIMD VF函数入口，使其可以被<a href="../../../api/SIMD-API/basic_api/reg_vector_compute/vf_call/asc_vf_call.html">asc_vf_call</a>调用。</p><p>simd_adds函数实现对UB上的数据做加1计算。函数中循环repeat_times次完成单核数据处理。input为SIMT阶段写入UB的gather结果，output为加1后的UB输出；本样例调用时input和output均传入local_output。one_repeat_size表示每轮处理的float元素个数，repeat_times表示完成count个元素所需的循环次数。</p><p>循环中，使用<a href="../../../api/SIMD-API/c_api/reg_compute/load/asc_loadalign.html">asc_loadalign</a>接口将数据从UB搬运到SIMD矢量数据寄存器，使用<a href="../../../api/SIMD-API/c_api/reg_compute/reg_arith/asc_add_scalar.html">asc_add_scalar</a>接口完成数据加1运算，使用<a href="../../../api/SIMD-API/c_api/reg_compute/store/asc_storealign.html">asc_storealign</a>接口将数据从SIMD矢量数据寄存器搬运到UB。</p></article></div>`,1)])])}const u=a(e,[["render",i]]);export{w as __pageData,u as default};
